import java.util.*;
import java.io.*;

public class Main {
    static final int N = 12;
    static final int INF = 1000000009;
    static final int[] delta_x = {0, 1, 0, -1};
    static final int[] delta_y = {1, 0, -1, 0};
    static int n, t;
    static char[][] gridA = new char[N][N];
    static char[][] gridB = new char[N][N];
    static int start_x, start_y;
    static int[][] dist = new int[N][N];

    static class Pos {
        int row, col;
        Pos() {}
        Pos(int _row, int _col) {
            this.row = _row;
            this.col = _col;
        }
    }

    static void do_bfs(int[][] d, int sx, int sy) {
        boolean[][] vis = new boolean[N][N];
        for (int i = 0; i < n; ++i)
            Arrays.fill(d[i], INF);
        Queue<Pos> q = new LinkedList<>();
        vis[sx][sy] = true;
        d[sx][sy] = 0;
        q.offer(new Pos(sx, sy));
        while (!q.isEmpty()) {
            Pos c = q.poll();
            for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                Pos nxt = new Pos(c.row + delta_x[dir_idx], c.col + delta_y[dir_idx]);
                if (nxt.row >= 0 && nxt.row < n && nxt.col >= 0 && nxt.col < n
                        && !vis[nxt.row][nxt.col]
                        && gridA[nxt.row][nxt.col] >= '0'
                        && gridA[nxt.row][nxt.col] <= '9') {
                    vis[nxt.row][nxt.col] = true;
                    d[nxt.row][nxt.col] = d[c.row][c.col] + 1;
                    q.offer(nxt);
                }
            }
        }
    }

    static boolean[][][][] residual_flow = new boolean[N * 6][N][N][N][N];
    static boolean[][] can_reach = new boolean[N][N][N][N];

    static int[][] g_matrix = new int[2 * N * N][2 * N * N];

    static int[] parent_node = new int[2 * N * N];
    static boolean[] visited_nodes = new boolean[2 * N * N];

    static boolean bfs_flow() {
        Arrays.fill(visited_nodes, false);
        Arrays.fill(parent_node, 0);
        Queue<Integer> q = new LinkedList<>();
        visited_nodes[0] = true;
        q.offer(0);
        while (!q.isEmpty()) {
            int node = q.poll();
            if (node == 2 * n * n + 1)
                return true;
            for (int h = 0; h <= 2 * n * n + 1; ++h) {
                if (g_matrix[node][h] != 0) {
                    if (!visited_nodes[h]) {
                        visited_nodes[h] = true;
                        parent_node[h] = node;
                        q.offer(h);
                    }
                }
            }
        }
        return false;
    }

    static void process() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; ++i)
            gridA[i] = sc.next().toCharArray();
        for (int i = 0; i < n; ++i)
            gridB[i] = sc.next().toCharArray();
        start_x = sc.nextInt();
        start_y = sc.nextInt();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (gridA[i][j] == 'Z') {
                    start_x = i;
                    start_y = j;
                }
        do_bfs(dist, start_x, start_y);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if ('0' <= gridA[i][j] && gridA[i][j] <= '9')
                    residual_flow[0][i][j][i][j] = true;
        for (int step = 0; step < t; ++step) {
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y) {
                            if (!residual_flow[step][sx][sy][x][y]) continue;
                            if (dist[x][y] <= step) continue;
                            for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                                int hx = x + delta_x[dir_idx];
                                int hy = y + delta_y[dir_idx];
                                if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= gridA[hx][hy] && gridA[hx][hy] <= '9') {
                                    if (dist[hx][hy] >= step + 1)
                                        residual_flow[step + 1][sx][sy][hx][hy] = true;
                                }
                            }
                        }
        }
        for (int step = 0; step <= t; ++step)
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y)
                            if (residual_flow[step][sx][sy][x][y])
                                can_reach[sx][sy][x][y] = true;

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                if ('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')
                    g_matrix[0][x1 * n + y1 + 1] = gridA[x1][y1] - '0';

        for (int x2 = 0; x2 < n; ++x2)
            for (int y2 = 0; y2 < n; ++y2)
                if ('0' <= gridB[x2][y2] && gridB[x2][y2] <= '9')
                    g_matrix[n * n + x2 * n + y2 + 1][2 * n * n + 1] = gridB[x2][y2] - '0';

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2) {
                        if (!('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')) continue;
                        if (!('0' <= gridA[x2][y2] && gridA[x2][y2] <= '9')) continue;
                        if (!can_reach[x1][y1][x2][y2]) continue;
                        g_matrix[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                    }

        while (bfs_flow()) {
            int min_flow_value = INF;
            for (int i = 2 * n * n + 1; i != 0; i = parent_node[i]) {
                min_flow_value = Math.min(min_flow_value, g_matrix[parent_node[i]][i]);
            }
            for (int i = 2 * n * n + 1; i != 0; i = parent_node[i]) {
                g_matrix[parent_node[i]][i] -= min_flow_value;
                g_matrix[i][parent_node[i]] += min_flow_value;
            }
        }

        int answer = 0;
        for (int i = 0; i <= 2 * n * n + 1; ++i)
            answer += g_matrix[i][0];

        System.out.println(answer);
        sc.close();
    }

    public static void main(String[] args) {
        process();
    }
}
